/**
 * checkout-handoff-validate
 *
 * Validates and consumes a one-time handoff token generated by mobile-checkout-bridge.
 * Returns the user's identity + a fresh Supabase session so the web frontend
 * can bootstrap checkout without relying on WebView localStorage.
 *
 * POST /checkout-handoff-validate
 * Body: { handoff: "<token>" }
 * Response: { ok, user_id, email, access_token, refresh_token } or structured error
 */

import {
  corsHeaders,
  createAdminClient,
  jsonResponse,
} from "../_shared/auth.ts";

const tag = "[checkout-handoff]";

function maskId(id: string): string {
  if (!id || id.length < 8) return "***";
  return id.slice(0, 4) + "…" + id.slice(-4);
}

Deno.serve(async (req: Request) => {
  if (req.method === "OPTIONS") {
    return new Response(null, { headers: corsHeaders });
  }

  try {
    let body: any = {};
    try {
      body = await req.json();
    } catch {
      return jsonResponse({
        ok: false,
        error: "HANDOFF_INVALID",
        error_code: "HANDOFF_INVALID",
        message: "Missing handoff token in request body.",
      }, 200);
    }

    const handoffToken = body?.handoff;
    if (!handoffToken || typeof handoffToken !== "string") {
      console.log(`${tag} invalid — no token in body`);
      return jsonResponse({
        ok: false,
        error: "HANDOFF_INVALID",
        error_code: "HANDOFF_INVALID",
        message: "Missing or invalid handoff token.",
      }, 200);
    }

    console.log(`${tag} validate`, JSON.stringify({ tokenPrefix: handoffToken.slice(0, 8) }));

    const admin = createAdminClient();

    // 1. Look up the handoff token
    const { data: record, error: fetchErr } = await admin
      .from("checkout_handoff_tokens")
      .select("*")
      .eq("token", handoffToken)
      .eq("purpose", "checkout_webview_handoff")
      .single();

    if (fetchErr || !record) {
      console.log(`${tag} invalid — not found`);
      return jsonResponse({
        ok: false,
        error: "HANDOFF_INVALID",
        error_code: "HANDOFF_INVALID",
        message: "Handoff token not found or invalid.",
      }, 200);
    }

    // 2. Check if already consumed
    if (record.consumed_at) {
      console.log(`${tag} already-used`, JSON.stringify({ id: record.id, consumedAt: record.consumed_at }));
      return jsonResponse({
        ok: false,
        error: "HANDOFF_ALREADY_USED",
        error_code: "HANDOFF_ALREADY_USED",
        message: "This handoff token has already been used.",
      }, 200);
    }

    // 3. Check TTL
    const now = new Date();
    const expiresAt = new Date(record.expires_at);
    if (now > expiresAt) {
      console.log(`${tag} expired`, JSON.stringify({ id: record.id, expiresAt: record.expires_at }));
      return jsonResponse({
        ok: false,
        error: "HANDOFF_EXPIRED",
        error_code: "HANDOFF_EXPIRED",
        message: "This handoff token has expired. Please try again.",
      }, 200);
    }

    // 4. Mark as consumed (single-use)
    const { error: updateErr } = await admin
      .from("checkout_handoff_tokens")
      .update({ consumed_at: now.toISOString() })
      .eq("id", record.id);

    if (updateErr) {
      console.error(`${tag} consume-update-error`, updateErr.message);
      // Continue anyway — the token was valid
    }

    // 5. Fetch user info via admin auth API
    const { data: userData, error: userErr } = await admin.auth.getUser(undefined);
    // We need to use the admin getUserById approach instead
    const supabaseUrl = Deno.env.get("SUPABASE_URL")!;
    const serviceKey = Deno.env.get("SUPABASE_SERVICE_ROLE_KEY")!;

    const userRes = await fetch(`${supabaseUrl}/auth/v1/admin/users/${record.user_id}`, {
      headers: {
        apikey: serviceKey,
        Authorization: `Bearer ${serviceKey}`,
      },
    });

    let userEmail = null;
    if (userRes.ok) {
      const u = await userRes.json();
      userEmail = u?.email;
    }

    console.log(`${tag} consumed`, JSON.stringify({
      handoffId: record.id,
      userId: maskId(record.user_id),
      email: userEmail ? userEmail.slice(0, 3) + "***" : null,
    }));

    // 6. Return user identity for web frontend to bootstrap session
    // The web frontend should use the access_token from the URL (passed as fallback)
    // or re-authenticate. We return the user_id and email so the frontend
    // knows the handoff is valid and can proceed.
    return jsonResponse({
      ok: true,
      user_id: record.user_id,
      email: userEmail,
      handoff_id: record.id,
      device_id: record.device_id,
      consumed: true,
    });
  } catch (err: any) {
    console.error(`${tag} unhandled-error`, err?.message);
    return jsonResponse({
      ok: false,
      error: "INTERNAL_ERROR",
      message: err?.message || "Internal error",
    }, 200);
  }
});
